<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import DashboardLayout from '@/layouts/DashboardLayout.vue';
import ApiAlert from '@/components/ApiAlert.vue';
import { api, errorMessage } from '@/api/client';
import type { ApiResponse } from '@/types/api';
type Chunk = { id:string; text:string; pageNumber:number; ordering:number };
type Document = { id:string; title:string; description:string; category:string; originalFilename:string; fileSize:number; fileHash:string; processingStatus:string; approvalStatus:string; processingError:string|null; warnings:string[]; pageCount:number; emptyPages:number[]; edition:number; version:number; publicOriginal:boolean; securityReviewed:boolean; uploadedBy:string; reviewedBy:string|null; reviewedAt:string|null; createdAt:string; updatedAt:string; chunks?:Chunk[]; page?:number; totalPages?:number; _count:{chunks:number} };
type Library = { items:Document[]; categories:string[]; maxBytes:number; total:number; page:number; totalPages:number };
const library = ref<Library>({items:[],categories:[],maxBytes:10485760,total:0,page:1,totalPages:0});
const selected = ref<Document|null>(null), busy=ref(false), loading=ref(false), error=ref(''), notice=ref(''), progress=ref(0), file=ref<File|null>(null), picker=ref<HTMLInputElement>(), confirmDelete=ref(false), reviewed=ref(false), allowOriginal=ref(false);
const search=ref(''), category=ref(''), status=ref(''), replacement=ref<{id:string;version:number;title:string}|null>(null);
const form=reactive({title:'',description:'',category:'School History'}), metadata=reactive({title:'',description:'',category:'School History'});
const originalUrl=(id:string)=>`${api.defaults.baseURL}/admin/ai-knowledge/${id}/original`;
async function load(page=1){loading.value=true;error.value='';try{library.value=(await api.get<ApiResponse<Library>>('/admin/ai-knowledge',{params:{page,search:search.value,category:category.value||undefined,status:status.value||undefined}})).data.data;}catch(e){error.value=errorMessage(e);}finally{loading.value=false;}}
async function open(id:string,page=1){error.value='';try{selected.value=(await api.get<ApiResponse<Document>>(`/admin/ai-knowledge/${id}`,{params:{page}})).data.data;Object.assign(metadata,{title:selected.value.title,description:selected.value.description,category:selected.value.category});reviewed.value=false;allowOriginal.value=selected.value.publicOriginal;confirmDelete.value=false;}catch(e){error.value=errorMessage(e);}}
function choose(event:Event){file.value=(event.target as HTMLInputElement).files?.[0]??null;error.value='';if(file.value&&(!/\.pdf$/i.test(file.value.name)||file.value.type!=='application/pdf'||file.value.size>library.value.maxBytes)){error.value='Choose a PDF within the displayed upload limit.';file.value=null;if(picker.value)picker.value.value='';}}
function newDocument(){replacement.value=null;Object.assign(form,{title:'',description:'',category:'School History'});file.value=null;if(picker.value)picker.value.value='';}
function replace(){if(!selected.value)return;newDocument();replacement.value={id:selected.value.id,version:selected.value.version,title:selected.value.title};Object.assign(form,{title:selected.value.title,description:selected.value.description,category:selected.value.category});notice.value='Choose the replacement PDF below. The approved edition stays available until the replacement is approved.';picker.value?.focus();}
async function upload(){if(!file.value||busy.value)return;busy.value=true;error.value='';notice.value='';progress.value=0;try{const data=new FormData();for(const [key,value]of Object.entries(form))data.append(key,value);data.append('document',file.value);if(replacement.value)data.append('version',String(replacement.value.version));const path=replacement.value?`/admin/ai-knowledge/${replacement.value.id}/replace`:'/admin/ai-knowledge';const saved=(await api.post<ApiResponse<Document>>(path,data,{headers:{'Content-Type':undefined},timeout:60000,onUploadProgress:e=>{progress.value=e.total?Math.round(e.loaded/e.total*100):0;}})).data.data;newDocument();await load();await open(saved.id);notice.value=saved.processingStatus==='FAILED'?'The PDF was stored, but extraction failed. Review the error and reprocess or remove it.':'PDF stored privately. Review its extracted text before approval.';}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}}
async function action(kind:'review'|'reprocess'|'metadata'|'delete',decision?:string){if(!selected.value||busy.value)return;const doc=selected.value;busy.value=true;error.value='';notice.value='';try{if(kind==='delete'){await api.delete(`/admin/ai-knowledge/${doc.id}`,{data:{version:doc.version}});selected.value=null;confirmDelete.value=false;}else{if(kind==='metadata')await api.patch(`/admin/ai-knowledge/${doc.id}`,{...metadata,version:doc.version});else await api.post(`/admin/ai-knowledge/${doc.id}/${kind}`,{version:doc.version,...(kind==='review'?{decision,confirmedPublicAndSafe:reviewed.value,publicOriginal:allowOriginal.value}:{})},{timeout:60000});await open(doc.id);}await load(library.value.page);notice.value=kind==='delete'?'Original and extracted passages permanently removed.':kind==='review'?'Document review saved.':kind==='metadata'?'Metadata updated. Approval is required again.':'Processing finished. Review the extraction before approval.';}catch(e){error.value=errorMessage(e);}finally{busy.value=false;}}
onMounted(()=>{void load();});
</script>
<template><DashboardLayout><section class="mx-auto max-w-5xl space-y-6 p-5 lg:p-10"><header><h1 class="text-h1">AI Knowledge Base</h1><p class="mt-3">Manage public school knowledge from PDFs and <RouterLink to="/admin/chatbot" class="underline">approved FAQs</RouterLink>.</p></header><ApiAlert :message="error"/><ApiAlert :message="notice" kind="success"/><p class="border bg-white p-4 text-sm">PDF originals are private. New uploads are quarantined until you review their safety, extraction and public-school content. Automated antivirus scanning and OCR are not configured. Never upload private student records, individual transcripts or confidential alumni information.</p>
<form class="space-y-4 border bg-white p-5" @submit.prevent="upload"><h2 class="text-h2">{{replacement?'Upload replacement PDF':'Upload a school PDF'}}</h2><p v-if="replacement">Replacing “{{replacement.title}}”.</p><label for="knowledge-title" class="field-label">Document title</label><input id="knowledge-title" v-model.trim="form.title" required minlength="3" maxlength="180" class="field-input" :disabled="busy"><label for="knowledge-description" class="field-label">Description</label><textarea id="knowledge-description" v-model.trim="form.description" maxlength="1200" class="field-input" :disabled="busy"/><label for="knowledge-category" class="field-label">Knowledge category</label><select id="knowledge-category" v-model="form.category" required class="field-input" :disabled="busy"><option v-for="item in library.categories" :key="item">{{item}}</option></select><label for="knowledge-pdf" class="field-label">PDF document (maximum {{library.maxBytes/1048576}} MB)</label><input id="knowledge-pdf" ref="picker" type="file" accept="application/pdf,.pdf" required :disabled="busy" class="block max-w-full" @change="choose"><p v-if="busy" role="status">{{progress<100?`Uploading PDF: ${progress}%`:'Processing PDF and preserving page references…'}}</p><progress v-if="busy" :value="progress" max="100" aria-label="PDF upload progress" class="w-full"/><div class="flex flex-wrap gap-3"><button class="primary-button" :disabled="busy||!file||loading">Upload PDF</button><button type="button" class="secondary-button" :disabled="busy" @click="newDocument">Start a new document</button></div></form>
<form class="grid gap-4 border bg-white p-5 sm:grid-cols-2" @submit.prevent="load()"><div><label for="knowledge-search" class="field-label">Search PDF library</label><input id="knowledge-search" v-model.trim="search" maxlength="150" class="field-input"></div><div><label for="knowledge-filter-category" class="field-label">Filter category</label><select id="knowledge-filter-category" v-model="category" class="field-input"><option value="">All categories</option><option v-for="item in library.categories" :key="item">{{item}}</option></select></div><div><label for="knowledge-filter-status" class="field-label">Approval status</label><select id="knowledge-filter-status" v-model="status" class="field-input"><option value="">All statuses</option><option v-for="item in ['PENDING','APPROVED','REJECTED','ARCHIVED','SUPERSEDED']" :key="item">{{item}}</option></select></div><button class="secondary-button self-end" :disabled="loading||busy">Search documents</button></form>
<p v-if="loading" role="status">Loading PDF library…</p><p v-else-if="!library.items.length">No matching PDFs.</p><article v-for="doc in library.items" :key="doc.id" class="space-y-3 border bg-white p-5"><h2 class="text-h2 break-words">{{doc.title}}</h2><p>{{doc.category}} · {{doc.approvalStatus}} · {{doc.processingStatus}} · Edition {{doc.edition}}</p><p class="text-sm">{{doc.pageCount}} pages · {{doc._count.chunks}} passages · {{(doc.fileSize/1024).toFixed(1)}} KB · {{doc.approvalStatus==='APPROVED'&&doc.securityReviewed?'Available to the assistant':'Excluded from assistant answers'}}</p><button class="secondary-button" :disabled="busy" @click="open(doc.id)">Review document</button></article><nav v-if="library.totalPages>1" aria-label="PDF library pages" class="flex items-center gap-4"><button class="secondary-button" :disabled="busy||loading||library.page<=1" @click="load(library.page-1)">Previous documents</button><span>{{library.page}} / {{library.totalPages}}</span><button class="secondary-button" :disabled="busy||loading||library.page>=library.totalPages" @click="load(library.page+1)">Next documents</button></nav>
<section v-if="selected" aria-label="Document extraction review" class="space-y-5 border bg-white p-5"><h2 class="text-h2 break-words">Review: {{selected.title}}</h2><dl class="grid gap-2 break-words text-sm sm:grid-cols-2"><div><dt class="font-semibold">Original filename</dt><dd>{{selected.originalFilename}}</dd></div><div><dt class="font-semibold">Processing and approval</dt><dd>{{selected.processingStatus}} · {{selected.approvalStatus}}</dd></div><div><dt class="font-semibold">Uploaded</dt><dd>{{new Date(selected.createdAt).toLocaleString()}}</dd></div><div><dt class="font-semibold">Last review</dt><dd>{{selected.reviewedAt?new Date(selected.reviewedAt).toLocaleString():'Awaiting review'}}</dd></div><div class="sm:col-span-2"><dt class="font-semibold">SHA-256</dt><dd class="break-all">{{selected.fileHash}}</dd></div></dl><ApiAlert :message="selected.processingError||''"/><p v-for="warning in selected.warnings" :key="warning" role="status">{{warning}}</p><p v-if="selected.emptyPages.length">Unreadable or empty pages: {{selected.emptyPages.join(', ')}}. Scanned pages need OCR outside this application; upload a corrected text PDF or add verified FAQs.</p><a :href="originalUrl(selected.id)" class="inline-block underline">Download private original for offline security review</a><form class="space-y-3 border-t pt-4" @submit.prevent="action('metadata')"><label for="metadata-title" class="field-label">Edit document title</label><input id="metadata-title" v-model.trim="metadata.title" required minlength="3" maxlength="180" class="field-input"><label for="metadata-description" class="field-label">Edit description</label><textarea id="metadata-description" v-model.trim="metadata.description" maxlength="1200" class="field-input"/><label for="metadata-category" class="field-label">Edit category</label><select id="metadata-category" v-model="metadata.category" class="field-input"><option v-for="item in library.categories" :key="item">{{item}}</option></select><button class="secondary-button" :disabled="busy||['PROCESSING'].includes(selected.processingStatus)||['ARCHIVED','SUPERSEDED'].includes(selected.approvalStatus)">Save document metadata</button></form><h3 class="font-semibold">Extracted passages (page references preserved)</h3><p v-if="!selected.chunks?.length">No readable passages available.</p><article v-for="chunk in selected.chunks" :key="chunk.id" class="border-l-4 p-3"><h4 class="font-semibold">Page {{chunk.pageNumber}} · Passage {{chunk.ordering+1}}</h4><p class="whitespace-pre-wrap break-words">{{chunk.text}}</p></article><nav v-if="(selected.totalPages||0)>1" aria-label="Extracted passage pages" class="flex flex-wrap items-center gap-3"><button class="secondary-button" :disabled="busy||(selected.page||1)<=1" @click="open(selected.id,(selected.page||1)-1)">Previous passages</button><span>{{selected.page}} / {{selected.totalPages}}</span><button class="secondary-button" :disabled="busy||(selected.page||1)>=(selected.totalPages||1)" @click="open(selected.id,(selected.page||1)+1)">Next passages</button></nav>
<div class="space-y-4 border-t pt-4"><label class="flex items-start gap-3"><input v-model="reviewed" type="checkbox" :disabled="busy" class="mt-1"><span>I reviewed the original offline for unsafe content and verified that the extracted text contains only accurate, public school information, with no private student or alumni records.</span></label><label class="flex items-start gap-3"><input v-model="allowOriginal" type="checkbox" :disabled="busy" class="mt-1"><span>Explicitly allow public download of this PDF original after approval.</span></label><div class="flex flex-wrap gap-3"><button class="primary-button" :disabled="busy||!reviewed||!['READY','NEEDS_REVIEW'].includes(selected.processingStatus)||selected.approvalStatus==='SUPERSEDED'" @click="action('review','APPROVED')">Approve for assistant</button><button class="secondary-button" :disabled="busy||selected.approvalStatus==='SUPERSEDED'" @click="action('review','REJECTED')">Reject document</button><button class="secondary-button" :disabled="busy||selected.approvalStatus==='SUPERSEDED'" @click="action('review','ARCHIVED')">Archive document</button><button class="secondary-button" :disabled="busy||['ARCHIVED','SUPERSEDED'].includes(selected.approvalStatus)" @click="action('reprocess')">Reprocess PDF</button><button v-if="selected.approvalStatus==='APPROVED'" class="secondary-button" :disabled="busy" @click="replace">Prepare replacement</button><button class="secondary-button" :disabled="busy||selected.processingStatus==='PROCESSING'" @click="confirmDelete=true">Remove document</button></div><section v-if="confirmDelete" role="alert" class="space-y-3 border p-4"><p>This permanently deletes the private original and all extracted passages. Existing citations will become unavailable.</p><button class="primary-button" :disabled="busy" @click="action('delete')">Confirm permanent removal</button><button class="secondary-button ml-3" :disabled="busy" @click="confirmDelete=false">Cancel removal</button></section></div></section>
</section></DashboardLayout></template>
